/**
 * Adds click handlers to ProcessSteps component elements for navigation.
 *
 * This utility function synchronizes DOM elements from the `@gemeente-denhaag/process-steps`
 * component with the stepper configuration, ensuring that:
 * - Only navigable steps become clickable
 * - Clicking navigates to the correct step marker (not DOM index)
 * - Non-navigable group steps are properly excluded
 * - Sub-steps are handled correctly
 *
 * ## How It Works
 *
 * The function iterates through the `processStepsConfig` array (generated by `stepper.generateSteps()`)
 * and matches each step configuration to its corresponding DOM element. This ensures that:
 * - DOM order matches config order
 * - Step markers from config are used for navigation (not DOM indices)
 * - Non-navigable steps are properly identified and excluded
 *
 * ## Usage
 *
 * ```javascript
 * import { addStepperClickHandlers } from '@utils';
 * import { useRef, useEffect } from 'react';
 * import useStepper from '@views/ac-forms/con-stepper';
 *
 * const MyWizard = () => {
 *   const stepper = useStepper();
 *   const processStepsRef = useRef(null);
 *
 *   const processStepsConfig = useMemo(() => {
 *     return stepper.generateSteps([
 *       { title: 'Step 1' },
 *       { title: 'Step 2', isNavigable: false, substeps: [
 *         { title: 'Sub-step 1' },
 *         { title: 'Sub-step 2' },
 *       ]},
 *       { title: 'Step 3' },
 *     ]);
 *   }, [stepper, stepper.getCurrentStep()]);
 *
 *   useEffect(() => {
 *     if (!processStepsRef.current) return;
 *     if (isLoading || hasError) return;
 *
 *     const cleanup = addStepperClickHandlers({
 *       processStepsRef,
 *       processStepsConfig,
 *       stepper,
 *     });
 *
 *     return cleanup;
 *   }, [stepper.getCurrentStep(), isLoading, hasError, processStepsConfig, stepper]);
 *
 *   return (
 *     <div ref={processStepsRef}>
 *       <ProcessSteps steps={processStepsConfig} />
 *     </div>
 *   );
 * };
 * ```
 *
 * ## Parameters
 *
 * @param {Object} options - Configuration options
 * @param {React.RefObject<HTMLElement>} options.processStepsRef - Ref to the container element containing the ProcessSteps component
 * @param {Array<Object>} options.processStepsConfig - Step configuration array from `stepper.generateSteps()`
 * @param {Object} options.stepper - Stepper instance from `useStepper()` hook
 * @param {number} [options.delay=100] - Delay in milliseconds before adding handlers (allows DOM to render)
 * @param {boolean} [options.skipIfLoading=false] - Skip adding handlers if loading state is true
 * @param {boolean} [options.skipIfError=false] - Skip adding handlers if error state is true
 *
 * @returns {Function} Cleanup function that removes all click handlers and classes
 *
 * @example
 * // Basic usage
 * const cleanup = addStepperClickHandlers({
 *   processStepsRef,
 *   processStepsConfig,
 *   stepper,
 * });
 *
 * @example
 * // With loading/error states
 * const cleanup = addStepperClickHandlers({
 *   processStepsRef,
 *   processStepsConfig,
 *   stepper,
 *   skipIfLoading: isLoading,
 *   skipIfError: hasError,
 * });
 */
export const addStepperClickHandlers = ({
  processStepsRef,
  processStepsConfig,
  stepper,
  delay = 100,
  skipIfLoading = false,
  skipIfError = false,
}) => {
  if (!processStepsRef?.current) {
    return () => {}; // Return no-op cleanup if ref is not available
  }

  if (skipIfLoading || skipIfError) {
    return () => {}; // Return no-op cleanup if should skip
  }

  const timeoutId = setTimeout(() => {
    const stepElements = processStepsRef.current.querySelectorAll(
      '.denhaag-process-steps .denhaag-process-steps__step-header, .denhaag-process-steps .denhaag-process-steps__sub-step'
    );

    let domIndex = 0; // Track position in DOM elements array

    processStepsConfig.forEach((stepConfig) => {
      // Get the step header element (always present for each config step)
      const stepHeader = stepElements[domIndex];
      if (!stepHeader) return;

      domIndex++; // Move past the header

      // Check if this step is navigable
      // Group steps check isNavigable property, single steps are always navigable
      const isNavigable = stepConfig.steps ? stepConfig.isNavigable !== false : true;

      const stepMarker = stepConfig.marker;
      const currentStep = stepper.getCurrentStep();

      // Reset styles and handlers
      stepHeader.style.cursor = '';
      stepHeader.onclick = null;
      stepHeader.classList.remove('ac-step-clickable');

      // Only make navigable steps clickable if they're before the current step
      if (isNavigable && stepMarker < currentStep) {
        stepHeader.classList.add('ac-step-clickable');
        stepHeader.onclick = (e) => {
          e.preventDefault();
          e.stopPropagation();
          stepper.setCurrentStep(stepMarker);
        };
      }

      // Handle sub-steps if this is a group
      if (stepConfig.steps) {
        stepConfig.steps.forEach((subStep) => {
          const subStepElement = stepElements[domIndex];
          if (!subStepElement) return;

          domIndex++; // Move past this sub-step

          // Sub-steps are always navigable
          const subStepMarker = subStep.marker;

          // Reset styles and handlers
          subStepElement.style.cursor = '';
          subStepElement.onclick = null;
          subStepElement.classList.remove('ac-step-clickable');

          // Make sub-step clickable if it's before the current step
          if (subStepMarker < currentStep) {
            subStepElement.classList.add('ac-step-clickable');
            subStepElement.onclick = (e) => {
              e.preventDefault();
              e.stopPropagation();
              stepper.setCurrentStep(subStepMarker);
            };
          }
        });
      }
    });
  }, delay);

  // Return cleanup function
  return () => {
    clearTimeout(timeoutId);
    // Remove all click handlers and classes
    if (processStepsRef?.current) {
      const stepElements = processStepsRef.current.querySelectorAll(
        '.denhaag-process-steps .denhaag-process-steps__step-header, .denhaag-process-steps .denhaag-process-steps__sub-step'
      );
      stepElements.forEach((el) => {
        el.style.cursor = '';
        el.onclick = null;
        el.classList.remove('ac-step-clickable');
      });
    }
  };
};
